using GraphApi.Models.USR.Mascotas;namespace GraphApi.Services.USR.Mascotas{    /// <summary>    /// Define las operaciones de negocio y persistencia para Mascotas.    /// </summary>    public interface IMascotasService    {        /// <summary>        /// Obtiene la lista de Mascotas con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadMascotas>> GetMascotas(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de Mascotas con filtros opcionales.        /// </summary>        /// <param name="mascotaID">Filtro opcional para MascotaID.</param>        /// <param name="usuarioID">Filtro opcional para UsuarioID.</param>        /// <param name="nombreUsuario">Filtro opcional para NombreUsuario.</param>        /// <param name="correoUsuario">Filtro opcional para CorreoUsuario.</param>        /// <param name="nombreMascota">Filtro opcional para NombreMascota.</param>        /// <param name="tipoMascotaID">Filtro opcional para TipoMascotaID.</param>        /// <param name="tipoMascota">Filtro opcional para TipoMascota.</param>        /// <param name="razaMascotaID">Filtro opcional para RazaMascotaID.</param>        /// <param name="razaMascota">Filtro opcional para RazaMascota.</param>        /// <param name="fechaNacimiento">Filtro opcional para FechaNacimiento.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetMascotasDynamic(            int? mascotaID,            int? usuarioID,            string? nombreUsuario,            string? correoUsuario,            string? nombreMascota,            int? tipoMascotaID,            string? tipoMascota,            int? razaMascotaID,            string? razaMascota,            DateTime? fechaNacimiento,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo Mascota.        /// </summary>        /// <param name="objInput">Datos para crear el Mascota.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadMascotas> CreateMascotas(            clCreateMascotas objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un Mascota.        /// </summary>        /// <param name="objInput">Datos para actualizar el Mascota, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadMascotas?> UpdateMascotas(            clUpdateMascotas objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un Mascota por su ID.        /// </summary>        /// <param name="nMascotasID">ID del Mascota a eliminar.</param>        Task<bool> DeleteMascotas(int nMascotasID);    }}